package thaumcraft.test;
import java.util.*;
import com.mojang.authlib.GameProfile;
import net.minecraft.core.*;
import net.minecraft.network.chat.Component;
import net.minecraft.server.level.*;
import net.minecraft.world.*;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.level.storage.TagValueInput;
import net.minecraft.util.ProblemReporter;
import net.minecraftforge.event.TickEvent;
import net.minecraftforge.event.server.ServerStartedEvent;
import net.minecraftforge.eventbus.api.listener.SubscribeEvent;
import net.minecraftforge.fml.common.Mod;
import thaumcraft.*;
import thaumcraft.golems.*;
import static thaumcraft.test.ThaumaturgyProbe.*;
@Mod.EventBusSubscriber(modid=Thaumcraft.MODID)
public final class MobilityProbe {
 public static final BlockPos Q=new BlockPos(520,205,8);static final UUID OWNER=UUID.fromString("6be7c45a-6764-4c37-b8d3-d719a6fdc023");static ServerPlayer p;static int ticks;static boolean done;
 public static final GolemDesign FLYER=new GolemDesign(3,1,1,3,3);
 static GolemBuilder press(ServerPlayer p,BlockPos q){p.level().removeBlock(q,false);p.level().setBlockAndUpdate(q,GolemContent.BUILDER.get().defaultBlockState());return (GolemBuilder)p.level().getBlockEntity(q);}
 static void complete(GolemBuilder b){while(b.working())check(b.insert("machina",Direction.DOWN,false),"Paid job could not consume Machina");check(!b.insert("machina",Direction.DOWN,false),"Completed job charged extra Machina");}
 static void preserveWorker(ServerPlayer p,GolemDesign d,BlockPos q,String name,Item item,int amount){var g=new WorkerGolem(GolemContent.GOLEM.get(),p.level());g.configure(p,d,q,4);g.setMode(2);g.cargo.setItem(0,new ItemStack(item,amount));g.setCustomName(Component.literal(name));g.setHealth(5);check(p.level().addFreshEntity(g),"Cannot save mobility worker");float health=g.getHealth();check(!g.causeFallDamage(20,1,p.level().damageSources().fall())&&g.getHealth()==health,"Special legs took fall damage");}
 static void rules(ServerPlayer p){levitator(p);var l=p.level();for(var e:l.getEntitiesOfClass(WorkerGolem.class,new net.minecraft.world.phys.AABB(Q).inflate(20)))e.discard();for(var q:BlockPos.betweenClosed(Q.offset(-8,-1,-4),Q.offset(10,-1,4)))l.setBlockAndUpdate(q,Blocks.STONE.defaultBlockState());var b=press(p,Q);b.output.clearContent();p.setPos(Q.getX()+.5,Q.getY()+1,Q.getZ()+.5);var menu=new GolemBuilderMenu(122,p.getInventory(),b);check(menu.clickMenuButton(p,5)&&b.draft.legs()==1&&menu.design().legs()==1,"Leg button/data did not select wheels");b.draft=new GolemDesign(0,0,0,3,1);GolemProbe.giveComponents(p,b.draft);check(b.start(p)&&p.getInventory().isEmpty()&&!b.edit(p,5),"Wheel payment or busy lock failed");complete(b);check(b.output.getItem(0).get(GolemContent.DESIGN.get()).equals(b.draft),"Wheel output lost legs");b.output.clearContent();
 b.draft=FLYER;GolemProbe.giveComponents(p,b.draft);var state=thaumcraft.research.ResearchService.state(p);thaumcraft.research.KnowledgeStore.write(p,state.stage("GOLEMFLYER",0));check(!b.start(p)&&!b.working()&&p.getInventory().countItem(Items.SLIME_BALL)==1,"Missing flyer research charged materials");thaumcraft.research.KnowledgeStore.write(p,state);check(b.start(p),"Flyer reservation failed knows="+FLYER.knows(p)+" valid="+b.valid(p)+" components="+FLYER.components());check(p.getInventory().isEmpty(),"Flyer left unpaid inventory "+p.getInventory());check(b.insert("machina",Direction.DOWN,false),"Flyer refused Machina");check(b.remaining()==FLYER.cost()-1&&!b.edit(p,5)&&!b.start(p),"Paid flyer job mutable or double paid");
 var legacy=press(p,Q.west(4));legacy.output.clearContent();legacy.draft=GolemDesign.BASIC;p.setPos(Q.getX()-3.5,Q.getY()+1,Q.getZ()+.5);GolemProbe.giveComponents(p,legacy.draft);check(legacy.start(p)&&legacy.insert("machina",Direction.DOWN,false),"Legacy pending fixture failed");var tag=legacy.saveWithoutMetadata(l.registryAccess());check(tag.get("pending") instanceof net.minecraft.nbt.CompoundTag pending&&!pending.contains("legs"),"Walker codec changed old paid-job format");legacy.loadWithComponents(TagValueInput.create(ProblemReporter.DISCARDING,l.registryAccess(),tag));check(legacy.working()&&legacy.remaining()==7&&legacy.total()==8,"Old paid job changed cost/progress");legacy.setChanged();
 preserveWorker(p,FLYER,Q.east(6).above(6),"Persistent flyer",Items.DIAMOND,19);preserveWorker(p,new GolemDesign(1,1,0,2,2),Q.east(8),"Persistent climber",Items.GOLD_INGOT,13);Thaumcraft.LOGGER.info("MOBILITY_WRITE_OK: atomic leg payment, research gates, locked paid job, legacy NBT, saved flyer/climber and fall immunity");}
 static void levitator(ServerPlayer p){var l=p.level();var at=Q.north(3);var block=thaumcraft.devices.DeviceContent.LEVITATOR.get();l.setBlockAndUpdate(at,block.defaultBlockState().setValue(thaumcraft.devices.AuraDeviceBlock.FACING,Direction.UP));var b=(thaumcraft.devices.LevitatorEntity)l.getBlockEntity(at);b.serverTick();check(b.fuel()==0,"Idle levitator consumed aura");thaumcraft.aura.AuraManager.addVis(l,at,10);var drop=new net.minecraft.world.entity.item.ItemEntity(l,at.getX()+.5,at.getY()+1.2,at.getZ()+.5,new ItemStack(Items.COBBLESTONE));drop.setDeltaMovement(net.minecraft.world.phys.Vec3.ZERO);l.addFreshEntity(drop);b.serverTick();check(drop.getDeltaMovement().y>0&&b.fuel()>0&&b.fuel()<1200,"Levitator did not apply paid lift");float fuel=b.fuel();drop.setDeltaMovement(net.minecraft.world.phys.Vec3.ZERO);l.setBlockAndUpdate(at.above(),Blocks.STONE.defaultBlockState());b.serverTick();check(b.fuel()==fuel&&drop.getDeltaMovement().lengthSqr()==0,"Beam passed through solid block");l.removeBlock(at.above(),false);l.setBlockAndUpdate(at,b.getBlockState().setValue(thaumcraft.devices.AuraDeviceBlock.POWERED,true));b.serverTick();check(b.fuel()==fuel&&drop.getDeltaMovement().lengthSqr()==0,"Powered levitator applied motion/charged");b.increaseRange(p);check(b.range()==16,"Levitator range cycle failed");var tag=b.saveWithoutMetadata(l.registryAccess());b.loadWithComponents(TagValueInput.create(ProblemReporter.DISCARDING,l.registryAccess(),tag));check(b.range()==16&&b.fuel()==fuel,"Levitator reserve/range not saved");drop.discard();l.removeBlock(at,false);Thaumcraft.LOGGER.info("MOBILITY_LEVITATOR_OK: paid physical lift, idle/redstone/solid blockage and saved range/reserve");}
 @SubscribeEvent public static void start(ServerStartedEvent e){String mode=System.getProperty("thaumcraft.thaumaturgyProbe","");if(!mode.equals("mobility-write")&&!mode.equals("mobility-read"))return;var l=e.getServer().overworld();for(int x=31;x<=33;x++)for(int z=-1;z<=1;z++)l.setChunkForced(x,z,true);l.setChunkForced(12,0,true);l.setChunkForced(11,0,true);p=new ServerPlayer(e.getServer(),l,new GameProfile(OWNER,"MobilityProbe"),ClientInformation.createDefault()){@Override public void sendSystemMessage(Component c,boolean o){}@Override public void sendOverlayMessage(Component c){}@Override protected ItemCooldowns createItemCooldowns(){return new ItemCooldowns();}};knowledge(p);}
 @SubscribeEvent public static void tick(TickEvent.ServerTickEvent.Post e){String mode=System.getProperty("thaumcraft.thaumaturgyProbe","");if(!mode.equals("mobility-write")&&!mode.equals("mobility-read")||done||++ticks<60)return;var l=e.server().overworld();if(mode.equals("mobility-write"))rules(p);else{levitator(p);
 var b=(GolemBuilder)l.getBlockEntity(Q);check(b!=null&&b.working()&&b.remaining()==FLYER.cost()-1&&b.draft.equals(FLYER),"Paid flyer job lost at restart");complete(b);check(b.output.getItem(0).get(GolemContent.DESIGN.get()).equals(FLYER),"Resumed press output lost leg design");var old=(GolemBuilder)l.getBlockEntity(Q.west(4));check(old.working()&&old.remaining()==7&&old.total()==8,"Legacy pending job lost at restart");complete(old);check(old.output.getItem(0).get(GolemContent.DESIGN.get()).equals(GolemDesign.BASIC),"Legacy job output changed");var workers=l.getEntitiesOfClass(WorkerGolem.class,new net.minecraft.world.phys.AABB(Q).inflate(20));check(workers.stream().anyMatch(g->g.hasCustomName()&&g.getCustomName().getString().equals("Persistent flyer")&&g.design().equals(FLYER)&&g.legs()==3&&g.isNoGravity()&&g.getNavigation() instanceof GolemNavigation.Hover&&g.cargo.getItem(0).getCount()==19&&g.getHealth()==5),"Saved flyer lost navigation/design/cargo/health");check(workers.stream().anyMatch(g->g.hasCustomName()&&g.getCustomName().getString().equals("Persistent climber")&&g.legs()==2&&g.getNavigation() instanceof GolemNavigation.Climber&&g.cargo.getItem(0).getCount()==13),"Saved climber lost navigation/cargo");Thaumcraft.LOGGER.info("MOBILITY_RESTART_OK: paid old/new jobs completed once; flyer/climber cargo, health, legs and navigation preserved");}
 check(l.getEntitiesOfClass(WorkerGolem.class,new net.minecraft.world.phys.AABB(GolemProbe.Q).inflate(16)).stream().anyMatch(g->g.hasCustomName()&&g.getCustomName().getString().equals("Persistent porter")&&g.legs()==0&&g.design().legs()==0&&g.cargo.getItem(0).getCount()==17&&g.getHealth()==7&&g.getNavigation() instanceof GolemNavigation.Ground),"Actual port.22 worker did not migrate as walker");Thaumcraft.LOGGER.info("MOBILITY_PORT22_OK: actual pre-update walker retained design, health and 17 cargo items");done=true;e.server().halt(false);}
}
